@startuml

class Customer {
  + Name : string
  + AccountNumber : string
}

class Broker {
  + Name : string
}

class InsuranceProduct {
  + Name : string
  + Price : float
}

class Contract {
  + DateSigned : date
  + BillingCycle : string
}

class Offer {
  + DateSent : date
  + Content : string
}

class ClaimCase {
  + CaseId : string
  + Status : string
}

class Estimator {
  + Name : string
  + Expertise : string
}

class EstimatorReport {
  + ReportDate : date
  + Findings : string
}

class CompensationDecision {
  + EligibleCosts : float
  + TotalAmount : float
}

class Payment {
  + PaymentDate : date
  + Amount : float
}

Broker "1" -- "*" Customer : manages
Customer "1" -- "*" Offer : receives
Customer "1" -- "*" Contract : signs
Customer "1" -- "*" ClaimCase : files
Customer "1" -- "*" Payment : receives
Contract "1" -- "1" InsuranceProduct : covers
Contract "1" -- "1" Offer : based on
ClaimCase "1" -- "*" EstimatorReport : evaluated by
Estimator "1" -- "*" EstimatorReport : issues
ClaimCase "1" -- "0..1" CompensationDecision : results in
CompensationDecision "1" -- "1" Payment : triggers
ClaimCase "1" -- "*" ClaimCase : can be split into

@enduml

